# owner: platform
"""Short absence notices to send home to parents."""

from datetime import date
from typing import List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student

def _format_day(day: date) -> str:
    return f"{day:%B} {day.day}, {day.year}"

def _join_days(days: List[date]) -> str:
    names = [_format_day(day) for day in days]
    if len(names) == 1:
        return names[0]
    return "; ".join(names[:-1]) + " and " + names[-1]

def _check_marks(
    student: Student, marks: List[Mark]
) -> None:
    ids = {mark.student_id for mark in marks}
    others = ids - {student.student_id}
    if others:
        names = ", ".join(sorted(others))
        raise ValueError(f"marks from others: {names}")

def _notice_text(student: Student, days: List[date]) -> str:
    if not days:
        raise ValueError("no absences to report")
    noun = "day" if len(days) == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    count = f"{len(days)} {noun}"
    dates = _join_days(days)
    return f"{name} missed {count} of class: {dates}."

# ---
def absence_notice(
    student: Student, marks: List[Mark]
) -> str:
    """Parent-facing notice for a student's absent days."""
    _check_marks(student, marks)
    return _notice_text(student, days_missed(marks))
